public:
    int countOdds(int low, int high) {
        if(low%2==0 and high%2==0)
            return (high-low)/2;
        else
            return (high-low)/2+1;
    }
};

class Solution(object):
    def countOdds(self, low, high):
        """
        :type low: int
        :type high: int
        :rtype: int
        """
        if low % 2 == 0:
            low += 1
        if high % 2 == 0:
            high -= 1
        return (high - low + 2) / 2
